// ─── CHART 14: Crisis Heatmap by Region ─────────────────────────────────────
const regionTierAvg = regionData.map(d=>{
  const regionCities = cities.filter(c=>c.region===d.r);
  const avgTier = regionCities.reduce((sum,c)=>sum+c.tier,0)/regionCities.length;
  return {r:d.r, avg:parseFloat(avgTier.toFixed(2))};
}).sort((a,b)=>b.avg-a.avg);

new Chart(document.getElementById('crisisHeatmap'), {
  type:'bar',
  data:{
    labels:regionTierAvg.map(d=>d.r),
    datasets:[{
      label:'Avg Crisis Tier',
      data:regionTierAvg.map(d=>d.avg),
      backgroundColor:regionTierAvg.map(d=>{
        if(d.avg>=4) return '#7d1d1dbb';
        if(d.avg>=3) return '#c0392bbb';
        if(d.avg>=2.5) return '#e67e22bb';
        if(d.avg>=2) return '#2980b9bb';
